"kind": "propose",
"summary": "The current revision's memory limit is too low, causing OOM kills. Increasing the memory limit should resolve this.",
"hypotheses": [
    {
        "root_cause_class": "memory_limit_too_low",
        "summary": "OOMKilled pods in revision 4 indicate the memory limit is insufficient.",
        "supporting": ["oom_killed_current_revision"],
        "contradicting": [],
        "missing": ["memory_data_available", "memory_at_limit_before_kill"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "Missing memory usage data prevents definitive analysis.",
        "supporting": ["memory_data_available"],
        "contradicting": ["oom_killed_current_revision"],
        "missing": ["container_memory"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-resources",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "reports",
        "uid": "uid-deployment-reports"
    },
    "params": {
        "containers": {
            "app": {
                "limits": {
                    "memory": "1536Mi"
                }
            }
        }
    },
    "expected_effect": "Higher memory limit should prevent OOMKilled errors for revision 4 pods.",
    "rationale": "OOMKilled exit code 137 confirms memory exhaustion. No earlier healthy revision (earlier_revision_healthy=unknown) and rollout_recent=false indicate this revision's limit is the issue. Increasing to 1536Mi (1.5x current 1Gi) addresses the likely cause without affecting other revisions.",
    "cited_evidence_ids": ["ev-pod_states", "ev-rollout_history", "ev-target_events"],
    "cited_predicates": ["oom_killed_current_revision", "rollout_recent", "earlier_revision_healthy"]
}
}
